import{_ as e,H as s,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"40 | Elasticsearch查询：怎么优化Elasticsearch的查询性能？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Elasticsearch 的索引机制","slug":"elasticsearch-的索引机制","link":"#elasticsearch-的索引机制","children":[]},{"level":2,"title":"面试准备","slug":"面试准备","link":"#面试准备","children":[]},{"level":2,"title":"优化方案","slug":"优化方案","link":"#优化方案","children":[{"level":3,"title":"优化分页查询","slug":"优化分页查询","link":"#优化分页查询","children":[]},{"level":3,"title":"增大刷新间隔","slug":"增大刷新间隔","link":"#增大刷新间隔","children":[]},{"level":3,"title":"批量提交","slug":"批量提交","link":"#批量提交","children":[]},{"level":3,"title":"优化不必要字段","slug":"优化不必要字段","link":"#优化不必要字段","children":[]},{"level":3,"title":"冷热分离","slug":"冷热分离","link":"#冷热分离","children":[]}]},{"level":2,"title":"其他常规优化","slug":"其他常规优化","link":"#其他常规优化","children":[{"level":3,"title":"优化垃圾回收","slug":"优化垃圾回收","link":"#优化垃圾回收","children":[]},{"level":3,"title":"优化 swap","slug":"优化-swap","link":"#优化-swap","children":[]},{"level":3,"title":"文件描述符","slug":"文件描述符","link":"#文件描述符","children":[]}]},{"level":2,"title":"面试思路总结","slug":"面试思路总结","link":"#面试思路总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"后端工程师的高阶面经/40｜Elasticsearch查询：怎么优化Elasticsearch的查询性能？.md","filePath":"后端工程师的高阶面经/40｜Elasticsearch查询：怎么优化Elasticsearch的查询性能？.md","lastUpdated":1795554391000}'),l={name:"后端工程师的高阶面经/40｜Elasticsearch查询：怎么优化Elasticsearch的查询性能？.md"};function c(r,a,p,E,h,n){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="_40-elasticsearch查询-怎么优化elasticsearch的查询性能" tabindex="-1">40 | Elasticsearch查询：怎么优化Elasticsearch的查询性能？ <a class="header-anchor" href="#_40-elasticsearch查询-怎么优化elasticsearch的查询性能" aria-label="Permalink to &quot;40 | Elasticsearch查询：怎么优化Elasticsearch的查询性能？&quot;">​</a></h1><p>你好，我是大明。今天我们学习 Elasticsearch 的另外一个关键主题——高性能。</p><p>如果你经常和 Elasticsearch 打交道，你十有八九遇到过 Elasticsearch 的性能问题。这也就是为什么在面试中我们经常会遇到 Elasticsearch 性能优化相关的问题。 那么今天我就带你看看怎么优化 Elasticsearch 的性能，在面试中赢得竞争优势。</p><p>我们先来看 Elasticsearch 的索引机制，它是我们理解 Elasticsearch 原理的关键。</p><h2 id="elasticsearch-的索引机制" tabindex="-1">Elasticsearch 的索引机制 <a class="header-anchor" href="#elasticsearch-的索引机制" aria-label="Permalink to &quot;Elasticsearch 的索引机制&quot;">​</a></h2><p>Elasticsearch 的索引和之前你已经学习过的数据库索引比起来，还是有很大不同的，它使用的是倒排索引。所谓的倒排索引是相对于“正排”索引而言的。在一般的文件系统中，索引是文档映射到关键字，而倒排索引正相反，是从关键字映射到了文档。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/1.png" alt=""></a></p><p>所以你可以想到，假如说没有倒排索引，你想要找到包含关键字“Elasticsearch”的文档，那么你需要遍历所有的文档，然后筛选出包含了“Elasticsearch”关键字的文档。而有了倒排索引，你就可以直接从关键字出发，找到“Elasticsearch”关键字对应的文档。</p><p>Elasticsearch 依赖于 Lucene 来维护索引，它的基本原理也很简单。</p><ul><li><p>每当写入一个新的文档的时候，根据文档的每一个字段，Elasticsearch 会使用分词器，把每个字段的值切割成一个个关键词，每一个关键词也叫做 Term。</p></li><li><p>切割之后，Elasticsearch 会统计每一个关键词出现的频率，构建一个关键词到文档 ID、出现频率、位置的映射，这个也叫做 posting list。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/2.png" alt=""></a></p><p>从图片里你可以看出来几个关键点。</p><ul><li><p>每个字段其实是分散统计的。</p></li><li><p>Elasticsearch 记录了两个位置信息，一个位置是指它是第几个词，另外一个偏移量是指整个关键词的起始位置。</p></li></ul><p>你可以想到，存在 Elasticsearch 里的文档数不胜数，那么就意味着一个字段会有非常多的关键词。比如说图片里的 desc 字段，如果你的系统有一亿用户，每个人写的内容都不一样，关键词就会非常多。</p><p>假如说你要查询的是 desc 里包含 Hello 这个关键字的文档，你首先就要在关键词表格里面找到 Hello 这一条。如果关键词都是随机的，那么肯定很难找。如果让你来设计，你肯定会让Elasticsearch 把这些关键词排序，比如说按照字母来排序。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/3.png" alt=""></a></p><p>当然，Elasticsearch 的设计者明显要高明很多。这种类似于查找单词的东西，在业界早就有成熟的方案，那就是前缀树（Trie Tree），也叫做字典树，而这个“关键词表格”在Elasticsearch 里面叫做 Term Dictionary。它们的目标是尽可能地把全部关键词组成的索引整个装进内存里。之所以是尽可能，而不是一定，是因为部分字段的关键词会非常多，确实装不进去。所以连前缀树都觉得这样的空间开销受不了。</p><p>而 Elastiscearch 更进一步，用了一个优化，就是所谓的 FST（Finite State Transducers）。这个 FST 的核心思想是连公共前缀、后缀也一并压缩了。真正的 FST 原理还是相当复杂的，但是我能给你一个非常直观的例子，让你秒懂它最基本的概念。</p><p>假如说你现在有两个关键词 cat 和 ct，两种数据结构看起来是这样的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/4.png" alt=""></a></p><p>这个图更加接近真实数据结构的定义，所以有点难以理解。你可以认为当你找到 3 的时候，如果是经过 0-1-3，那么你知道前缀是 ct，并且你能够得到 ct 在 Term Dictionary 的位置。</p><p>这个位置，就是这个 ct 所在的 Block。但是你也可以想到，可能还有别的关键词 cta、ctb 等等，都是使用这个前缀的。如果几千个关键词都共享某个前缀，在一个 Block 内部怎么找？</p><p>其实 Elasticsearch 会在 Block 内部有很多的关键词的时候，进一步切割成所谓的 FloorBlock。每个 Floor Block 使用第一个关键词的首字母来加快查找。</p><p>而在 Block 或者 Floor Block 内部，都是通过遍历来查找对应的关键词的。因此整个结构看起来是下面这样的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/5.png" alt=""></a></p><p>因此你可以把这个查找关键词的过程理解成两步。</p><ol><li><p>根据 FST 找到 Block。</p></li><li><p>在 Block 里面遍历找到关键词。如果 Block 进一步细分为 Floor Block，就先根据前缀找到Floor Block，然后再去遍历 Floor Block。</p></li></ol><p>找到了关键词，也就找到了这个关键词对应的 posting list，那么就可以根据文档 ID 来找到具体的文档了。</p><h2 id="面试准备" tabindex="-1">面试准备 <a class="header-anchor" href="#面试准备" aria-label="Permalink to &quot;面试准备&quot;">​</a></h2><p>除了刚刚我们说的这些基础知识，你还要了解清楚公司内部一些和 Elasticsearch 有关的数据。</p><ul><li><p>你们公司 Elasticsearch 是如何部署的，有几个节点，每个节点上面的内存有多大，这些内存是怎么分配的？</p></li><li><p>你们公司 Elasticsearch 上 JVM 的配置是什么，垃圾回收用的是哪个，垃圾回收停顿的时间有多长？</p></li><li><p>你们公司 Elasticsearch 的哪些配置和默认值不一样，为什么修改？</p></li><li><p>你们公司 Elasticsearch 的性能怎么样，能撑住多大的读写流量？</p></li></ul><p>如果你本身对 Elasticsearch 性能优化不是很了解的话，我不是特别建议你在简历或者自我介绍的时候提起 Elasticsearch 性能优化。但是如果你很擅长，那么你就可以特意强调一下，因为这足以成为你竞争优势。</p><p>应该说，能用好数据库、Redis 和消息队列的人很多，但是能用好 Elasticsearch 的人就很少。如果你非常了解怎么优化 Elasticsearch，平时也做过一些优化，在面试的时候就一定要提起这一点，这是非常大的竞争优势。</p><h2 id="优化方案" tabindex="-1">优化方案 <a class="header-anchor" href="#优化方案" aria-label="Permalink to &quot;优化方案&quot;">​</a></h2><p>你在面试的时候并不需要记住全部的优化方案，而是可以尝试记住里面几个典型的，或者根据我在这里写出来的思路，结合自己的业务设计几个面试方案。</p><p>实际上，Elasticsearch 里可以优化的点非常多，这里我筛选出了比较适合面试的方案。有一些优化的点就是简单调整一下参数，又不能引导到别的话题，这里我就没有罗列出来。你有兴趣可以自己进一步了解。</p><h3 id="优化分页查询" tabindex="-1">优化分页查询 <a class="header-anchor" href="#优化分页查询" aria-label="Permalink to &quot;优化分页查询&quot;">​</a></h3><p>这个优化思路是很好的面试点，因为它可以和分库分表结合在一起。在分库分表的那一节课我深入讨论了分页查询为什么性能那么差，而在 Elasticsearch 里面也一样有这个问题。在Elasticsearch 里面，当你执行分页查询的时候，是使用 FROM X SIZE Y 的语法，基本等同于SQL 里的 OFFSET X LIMIT Y。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>也就是说，如果你的查询命中了 Elasticsearch 的 N 个分片，那么最终查询的数据量是 N *</span></span>
<span class="line"><span>(X + Y）。如果你已经忘了，记得回去复习一下。</span></span></code></pre></div><p>在 Elasticsearch 里面，也有两种可行的优化手段。</p><ol><li><p>Scroll 和 Scroll Scan：这种方式适合一次性查询大量的数据，比如说导出数据之类的场景。这种用法更加接近你在别的语言或者中间件里面接触到的游标的概念。</p></li><li><p>Search After：也就是翻页，你在查询的时候需要在当次查询里面带上上一次查询中返回的search_after 字段。</p></li></ol><p>在面试的时候，我建议你使用 Search After 来回答，因为 Search After 适用的场景更加广泛。</p><ul><li><p>我还优化过 Elasticsearch 的分页查询，也就是用 Search After 来优化的。Search After 就有点类似于分库分表中使用的禁用跳页查询的方案，也就是不支持随机翻页。每次查询都带上上一次查询的 search_after 字段。</p></li><li><p>它的优点就是查询的数据量不再和偏移量有关，只和每一页的大小，以及命中的分片数量有关。之前我在分库分表里面也优化过类似的分页查询，不过分库分表本身没有 search_after之类的字段，只能是我自己在业务层面上搞出来一个类似的 search_after。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>注意，这里的 search_after 就类似于分库分表中禁用跳页查询里面加入的 WHERE id &gt;</span></span>
<span class="line"><span>$max_id 这种极值过滤条件。</span></span></code></pre></div><h3 id="增大刷新间隔" tabindex="-1">增大刷新间隔 <a class="header-anchor" href="#增大刷新间隔" aria-label="Permalink to &quot;增大刷新间隔&quot;">​</a></h3><p>上一节课你已经学到了数据最开始是写入到 Buffer 中，然后经过 refresh 才被写入到 PageCache。那么你基本上可以预计，如果频繁地把数据刷新到 Page Cache 里，性能会有损耗。因此一个比较简单的优化方案就是调大这个刷新间隔。</p><ul><li>之前我优化 Elasticsearch 的时候，把 index.refresh_interval 调大到了 30。调整之后，性能大概提升了 20%。</li></ul><p>你可以尝试在自己的业务里面调整这个参数，看看性能提升的幅度。</p><h3 id="批量提交" tabindex="-1">批量提交 <a class="header-anchor" href="#批量提交" aria-label="Permalink to &quot;批量提交&quot;">​</a></h3><p>这也是你在前面的内容里面见过的优化手段，你记得复习一下之前对批量提交为什么能提高性能的分析，你在面试 Elasticsearch 的时候一样用得到。</p><p>批量提交也有两种策略。第一种策略是化单个为批量。</p><ul><li><p>早期我有一个业务，就是把数据库里的数据同步到 Elasticsearch。最开始的时候是每次用户更新了数据，就直接更新 Elasticsearch。但是这样效果很不好，因为用户基本上都是一条条数据更新。</p></li><li><p>后来我考虑到这个业务对数据一致性的要求不是很高，我就把实时同步修改成了异步同步，也就是定时扫描数据库中发生变化的数据，然后批量提交变更数据到 Elasticsearch。这个异步任务我设置的是每秒钟同步一次，和原来每一次写请求都要操作 Elasticsearch 比起来，压力小多了。同时业务方的响应时间也下降了 50%。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/6.png" alt=""></a></p><p>这种单个转批次的方案还可以用在 Kafka 和 Elasticsearch 结合使用的方案中。也就是有些公司的架构把数据写入到 Elasticsearch 的时候，并不是直接写入的，而是统一写入到 Kafka，然后再由一些消费者把 Kafka 里的数据写入到 Elasticsearch。</p><p>那么这里你就可以给出一个利用批量提交来解决消息积压问题的方案。</p><ul><li><p>我们公司的很多业务都不是直接同步数据到 Elasticsearch，而是要经过一个 Kafka，然后由 Kafka 的消费者把数据写入到 ElasticSearch。但是随着业务的增长，越来越多的数据要写入到 Elasticsearch，尤其是在业务高峰期，很容易产生消息积压的问题。</p></li><li><p>为了解决这个问题，我做了一个优化，就是批量消费，批量提交到 Elasticsearch。也就是说，早期 Kafka 的消费者是每次消费一条消息，就写一条数据到 Elasticsearch。而我现在改成了一次拉取 100 条消息（这个应该是可配置的），做成一个批次，提交给Elasticsearch，就解决了消息积压的问题。</p></li></ul><p>这个方案的好处就是你能够把消息积压和 Elasticsearch 的知识点联系在一起，能够从这个案例里看出你的思维很灵活。当然，这也会将话题引导到 Kafka 或者消息积压上，你要记得复习。</p><p>另外一个是调整批次。这一类手段非常适合用在日志同步中，我这里给出一个调整批次和降级的方案。</p><ul><li><p>我们公司的日志都是要利用 Logstash 直接同步到 Elasticsearch 的。那么在业务繁忙的时候，日志就有可能同步得很慢，或者 Elasticsearch 压力很大。在这种情况下，我把日志同步到 Elasticsearch 的批次调大了一些，显著降低了 Elasticsearch 的负载。</p></li><li><p>而且，我还引入了一个降级机制。正常我们公司的日志是全量同步的，但是如果发现Elasticsearch 有问题，就会触发降级，触发降级的时候就会先丢弃 INFO 级别的日志。运行一段时间之后，如果 Elasticsearch 还是没能恢复正常，就把 WARN 级别的也丢弃。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/7.png" alt=""></a></p><p>这一个方案亮点在于你把调整批次和降级结合在一起，能体现你综合运用各种手段解决实际问题的能力。</p><h3 id="优化不必要字段" tabindex="-1">优化不必要字段 <a class="header-anchor" href="#优化不必要字段" aria-label="Permalink to &quot;优化不必要字段&quot;">​</a></h3><p>有些时候，最开始设计索引的人可能没有注意，就把一些根本不会搜索到的字段也存储到了Elasticsearch。更加可怕的是还使用了动态的 mapping，这可能无意间索引了很多新字段。</p><p>在实践中最常见的错误，就是把数据库里存储的数据全量同步到 Elasticsearch 上。但是其实根本没有必要。所以这种优化手段就是只把要被查询的字段同步到 Elasticsearch 上，而把数据的主体部分留在原本的数据库里。</p><ul><li><p>之前我接手的一个历史系统需要把数据同步到 Elasticsearch 上支持搜索。但是最开始的时候数据量并不是很大，所以是直接把全量数据同步到了 Elasticsearch 上的。后面业务起来之后，就发现我这个业务的数据占据了大量的内存和磁盘空间。</p></li><li><p>我在梳理了业务之后发现其实不用全部同步过去的，因为要被搜索的字段只是其中的一小部分，而另外一些字段同步过去只是白白加重了 Elasticsearch 的负担。所以我后面就修改了同步的过程，那一部分数据就直接传入 null 了。查询过程就相当于在 Elasticsearch 上根据</p></li><li><p>各种输入查到业务的主键，如果还需要 Elasticsearch 中没有的字段，就回数据库再次查询。</p></li><li><p>当然，这样做的代价就是有一些查询需要再次查询数据库。但是我评估过这个，受影响的请求不足 10%，所以这个结果还是可以接受的。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/8.png" alt=""></a></p><p>少同步一些数据，就意味着你的索引所需的内存、磁盘更少，所以查询速度也会更快。紧接着补充一个 reindex 的改进计划。</p><ul><li>不过后续我也在考虑重新创建一个索引，现在这种有字段但是不同步数据的方式不太优雅。</li></ul><p>这种同步部分数据的手段，在日志检索中也很常见。毕竟日志一般都非常长，而搜索一般都是根据业务 ID 之类的来查询。</p><p>你还可以尝试在这个地方把话题引导到分库分表中间表上。</p><ul><li><p>这种二次查询类似于分库分表中利用中间表来支持一些无分库分表键查询的解决方案，都是要先在一个地方用查询条件拿到主键或者分库分表键，然后再到具体的数据库上查询到完整</p></li><li><p>的数据。</p></li></ul><p>如果你不记得了，记得回去复习一下。</p><h3 id="冷热分离" tabindex="-1">冷热分离 <a class="header-anchor" href="#冷热分离" aria-label="Permalink to &quot;冷热分离&quot;">​</a></h3><p>冷热分离应该算是一个业界非常常用的方案了。它的基本思路是同一个业务里面数据也有冷热之分。对于冷数据来说，可以考虑使用运行在廉价服务器上的 Elasticsearch 来存储；而对于热数据来说，就可以使用运行在昂贵的高性能服务器上的 Elasticsearch。</p><ul><li><p>之前我在公司的时候做过一个 Elastisearch 优化，就是冷热数据分离存储。我们的数据最开始都是存在统一规格的 Elasticsearch 上，然后这两年经济不太好，就想着降本增效，于是我们就决定试试业界用得比较多的冷热分离方案。</p></li><li><p>基本的思路是整个 Elasticsearch 的节点分成冷热两类，数据最开始都是写入到热节点上。等过一段时间之后，数据已经不热了，就迁移到冷节点上。</p></li><li><p>这部分我们是借助了新出来的索引生命周期特性来实现的。比如说我们的日志，就是三天内的数据都在热节点上，三天之后就是迁移到了冷节点上。这个过程都是自动的，不需要人工介入。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/9.png" alt=""></a></p><p>利用生命周期管理功能实现冷热数据分离操作起来还是很简单的，你可以考虑通过 Kibana 来直接在界面傻瓜式操作。而且一些云服务厂商也提供了这种功能，使用起来都很便捷。</p><p>我建议你在实践中操作一下再出去面试，最好是根据自己的业务来定制。比如说我在前面的回答里面用的是日志的例子，那么你可以把它替换成你的业务数据。</p><p>这种冷热分离的思路不仅仅可以在 Elasticsearch 中使用，我在微服务治理、缓存中也多次提到过类似的思路，所以如果你有机会，可以尝试引导话题。</p><h2 id="其他常规优化" tabindex="-1">其他常规优化 <a class="header-anchor" href="#其他常规优化" aria-label="Permalink to &quot;其他常规优化&quot;">​</a></h2><p>这部分之所以叫做常规优化，是因为正常生产环境上的 Elasticsearch 都优化过了，因此你可以简要说明一下。</p><h3 id="优化垃圾回收" tabindex="-1">优化垃圾回收 <a class="header-anchor" href="#优化垃圾回收" aria-label="Permalink to &quot;优化垃圾回收&quot;">​</a></h3><p>如果你本身是 Java 开发，那么非常建议你使用这个优化。就像我在 Kafka 里面提到的，你出去面试 Java 岗位，很重要的一点就是展示你在 JVM 上的深厚功力。</p><p>一般 Elasticsearch 优化垃圾回收的第一个思路就是调整垃圾回收算法。Elasticsearch 需要一个很大的堆，那么 CMS 是肯定撑不住的，停顿时间会非常长。</p><p>所以你可以考虑把垃圾回收算法换成 G1，或者更加激进的 ZGC。现在用 G1 比较多，所以你可以尝试用 G1 来回答。</p><ul><li><p>长期以来我们使用 Elasticsearch 有一个很大的问题，就是触发垃圾回收的时候，停顿时间比较长，会有一百多毫秒。这主要是因为我们的 Elasicsearch 用的都还是非常古老的CMS，而 CMS 在超过 8G 的堆上面，表现就比较差。</p></li><li><p>所以后面我就尝试将 Elasticsearch 换成了 G1，换了之后效果是非常不错，现在停顿时间都可以控制在 15ms 以内。不过我也在调研 ZGC，ZGC 在特大堆上的表现比 G1 还要好。不过目前这方面业界的实践不多，所以我也没有进一步优化。</p></li></ul><p>使用这个方案的核心就是把话题引导到垃圾回收这个主题上。</p><h3 id="优化-swap" tabindex="-1">优化 swap <a class="header-anchor" href="#优化-swap" aria-label="Permalink to &quot;优化 swap&quot;">​</a></h3><p>之前我们在讨论 Kafka 的时候就提到过优化 swap 这个措施，想必你对 swap 应该感觉非常熟悉了。</p><p>Elasticsearch 也是一个内存依赖非常严重的中间件，在触发了 swap 的时候，性能下降得很快。你有两种做法，第一种做法是在操作系统层面上直接禁用了 swap，或者把vm.swappness 设置成一个非常小的值。第二种做法是在 Elasticsearch 里把bootstrap.memory_lock 设置成 true。</p><p>在面试的时候你要注意把 Elasticsearch 和其他中间件联系在一起，这里我们以 Kafka 为例来说一说。</p><ul><li>使用 Elasticsearch 的时候要把 swap 禁用，或者把 vm.swappness 设置得很小，也可以把bootstrap.memory_lock 设置成 true。所有类似于 Elasticsearch 的中间件都可以采用这种优化手段，比如说 Kafka。</li></ul><h3 id="文件描述符" tabindex="-1">文件描述符 <a class="header-anchor" href="#文件描述符" aria-label="Permalink to &quot;文件描述符&quot;">​</a></h3><p>Elasticsearch 需要非常多的文件描述符，所以正常来说都需要把文件描述符的数量调大，比如说调到 65536，甚至更多。</p><p>你可以用解决 Bug 的思路来面试，比如说面试官问到你遇到过 Elasticsearch 什么 Bug 的时候，就可以用这个来回答。</p><ul><li><p>之前我们在使用 Elasticsearch 的时候，还遇到过文件描述符耗尽的问题。这是因为我们用的是一个非常大的 Elasticsearch，很多业务共用，导致 Elasticsearch 打开的文件描述符非常多。</p></li><li><p>那一次的故障之后，一方面我们是调大了最大文件描述符的数量，另外一方面也是考虑把业务逐步迁移到不同的 Elasticsearch 上。毕竟这一次故障，直接导致了我们好几个核心业务</p></li><li><p>都出问题了，足以说明还是要考虑隔离的。</p></li></ul><p>这个回答你还提到了隔离，如果面试官感兴趣，你就可以把话题引导到微服务的隔离上去。</p><h2 id="面试思路总结" tabindex="-1">面试思路总结 <a class="header-anchor" href="#面试思路总结" aria-label="Permalink to &quot;面试思路总结&quot;">​</a></h2><p>经过前面 MySQL 优化、Redis 优化、Kafka 优化，再加上这节课的 Elasticsearch 优化，你其实可以总结出一般性的性能优化方案。</p><p>实际上任何查询，不管是关系型数据库还是非关系型数据的查询，优化起来就是这几个方向。</p><ul><li><p>优化查询本身：这可能涉及到改写 SQL、优化索引等。</p></li><li><p>优化中间件本身：通常也就是调整一下中间件的各种参数，只有一些大厂在具备足够强的实力的情况下，会考虑二次开发。如果中间件本身是基于 JVM 的，那么也可以优化 JVM。</p></li><li><p>优化操作系统：目前你接触到的大多数中间件应该都是对内存、网络 IO 和磁盘 IO 有很强依赖，那么优化也就是调整跟这三个方面有关的参数。</p></li></ul><p>如果你的工作经历里面出现了这个课程里没有讨论过的中间件，你也可以按照类似的思路去准备面试用的性能优化方案。当然，要是你所在公司的运维团队非常强，你就直接问他们是如何优化性能的就可以，在面试中你同样用得上。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/40/10.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后请你来思考两个问题。</p><ul><li><p>我在这节课里面列出了很多优化方案，你还知道别的优化方案吗？如果你出去面试，你准备用什么话术来介绍你的优化方案？</p></li><li><p>在冷热分离中，一般冷数据我们的都是用机械硬盘，而热数据就是用固态硬盘，你知道这是为什么吗？</p></li></ul><p>欢迎你把自己的思考分享到评论区，也欢迎你把这节课的内容分享给需要的朋友，我们下节课再见！</p>`,107)])])}const u=e(l,[["render",c]]);export{B as __pageData,u as default};
